const SESSION_MAX_AGE_REMEMBER = 30 * 24 * 60 * 60; // 30 dias

// ─── Helpers ──────────────────────────────────────────────────────────────────
function esc(str: any): string {
  if (str == null || str === false) return "";
  const s = typeof str !== "string" ? String(str) : str;
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function fmtCurrency(val: number | string): string {
  const n = typeof val === "string" ? parseFloat(val) : val;
  return n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

function fmtPhone(phone: string): string {
  if (!phone) return "";
  const d = phone.replace(/\D/g, "");
  if (d.length === 11) return `(${d.slice(0,2)}) ${d.slice(2,7)}-${d.slice(7)}`;
  if (d.length === 10) return `(${d.slice(0,2)}) ${d.slice(2,6)}-${d.slice(6)}`;
  return phone;
}

function fmtDate(dateStr: string): string {
  const [y, m, d] = dateStr.split("-");
  return `${d}/${m}/${y}`;
}

function fmt(n: number): string {
  return n.toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function today(): string {
  return new Date().toISOString().split("T")[0];
}
function yesterday(): string {
  const d = new Date();
  d.setDate(d.getDate() - 1);
  return d.toISOString().split("T")[0];
}

/**
 * Envolve qualquer handler de rota GET com try/catch global.
 * Em caso de erro de banco ou erro inesperado, exibe uma página de erro amigável
 * em vez de deixar a requisição travar ou retornar um erro 500 sem corpo.
 */
function withErrorPage(
  pageName: string,
  activeMenu: string,
  fn: (req: Request, res: Response) => Promise<void>
) {
  return async (req: Request, res: Response) => {
    // Make trialInGrace available inside handlers
    (res as any).trialGrace = (req as any).trialInGrace ?? null;
    try {
      await fn(req, res);
    } catch (err: any) {
      console.error(`[${pageName}] Erro ao renderizar:`, err?.message ?? err);
      let barberName = "";
      let tenantPlan = "";
      try {
        const session = (req as any).adminSession as { barberId: number } | undefined;
        if (session?.barberId) {
          const b = await db.getBarberById(session.barberId);
          barberName = b?.name ?? "";
          if (b?.tenantId) {
            const t = await db.getTenantById(b.tenantId);
            tenantPlan = (t as any)?.plan ?? "";
          }
        }
      } catch { /* ignora */ }
      const retryUrl = req.originalUrl;
      const errorBody = `
        <div style="padding:60px 24px;text-align:center;max-width:480px;margin:0 auto">
          <div style="font-size:48px;margin-bottom:16px">⚠️</div>
          <h2 style="color:var(--text);margin-bottom:8px;font-size:20px">Erro ao carregar página</h2>
          <p style="color:var(--muted);margin-bottom:24px;font-size:14px;line-height:1.6">
            Ocorreu um problema de conexão com o banco de dados.<br>
            Aguarde alguns segundos e tente novamente.
          </p>
          <a href="${retryUrl}" class="btn btn-primary" style="display:inline-block;padding:12px 28px;background:var(--gold);color:#0C0C0C;border-radius:10px;font-weight:700;text-decoration:none;font-size:14px">Tentar novamente</a>
        </div>
      `;
      res.status(503).send(adminLayoutWithGrace(res, pageName, activeMenu, errorBody, barberName, tenantPlan));
    }
  };
}

function monthRange(): { start: string; end: string } {
  const now = new Date();
  const start = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-01`;
  const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
  const end = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${lastDay}`;
  return { start, end };
}

// ─── Sessão simples (JWT-less, cookie assinado com barberId) ──────────────────────────────────────────────────────────
function encodeSession(barberId: number, role: string, maxAge = SESSION_MAX_AGE): string {
  const payload = Buffer.from(JSON.stringify({ barberId, role, ts: Date.now(), maxAge })).toString("base64url");
  return payload;
}

function decodeSession(token: string): { barberId: number; role: string } | null {
  try {
    const data = JSON.parse(Buffer.from(token, "base64url").toString("utf-8"));
    if (!data.barberId || !data.role) return null;
    // Usar maxAge armazenado no token (suporta 8h ou 30 dias)
    const maxAge = data.maxAge ?? SESSION_MAX_AGE;
    if (Date.now() - data.ts > maxAge * 1000) return null;
    return { barberId: data.barberId, role: data.role };
  } catch {
    return null;
  }
}

// ─── Middleware de autenticação ────────────────────────────────────────────────────────────
function requireAdminAuth(req: Request, res: Response, next: NextFunction) {
  const token = req.cookies?.[ADMIN_SESSION_COOKIE];
  const isApiCall = req.path.startsWith('/admin-api/') || (req.headers['content-type'] ?? '').includes('application/json');
  if (!token) {
    if (isApiCall) return res.status(401).json({ error: 'Sessao expirada. Faca login novamente.' });
    return res.redirect('/admin/login');
  }
  const session = decodeSession(token);
  if (!session) {
    // Clear invalid/expired cookie to force clean login
    res.setHeader("Set-Cookie", `${ADMIN_SESSION_COOKIE}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0`);
    if (isApiCall) return res.status(401).json({ error: 'Sessao invalida. Faca login novamente.' });
    return res.redirect('/admin/login');
  }
  (req as any).adminSession = session;
  next();
}

// Middleware assíncrono que verifica se a assinatura Barber Pro está ativa/trial.
// Se expirada ou cancelada, redireciona para a aba de pagamentos com aviso.
// Rotas de pagamentos e configurações são sempre permitidas para não criar loop.
async function requireActiveSubscription(req: Request, res: Response, next: NextFunction) {
  try {
    const ALWAYS_ALLOWED = ["/admin/configuracoes", "/admin/login", "/admin/logout", "/admin/meu-perfil"];
    const isAlwaysAllowed = ALWAYS_ALLOWED.some(p => req.path === p || req.path.startsWith(p + "/") || req.path.startsWith("/admin/configuracoes/asaas"));
    if (isAlwaysAllowed) return next();

    const session = (req as any).adminSession as { barberId: number; role: string } | undefined;
    if (!session) return next();

    const barber = await db.getBarberById(session.barberId);
    if (!barber?.tenantId) return next();

    const dbConn = await db.getDb();
    if (!dbConn) return next();

    const rows = await dbConn.execute(
      `SELECT "barberproSubscriptionStatus", "trialEndsAt" FROM tenants WHERE id = ${barber.tenantId} LIMIT 1` as any
    );
    const t = ((rows as any).rows as any[])[0];
    if (!t) return next();

    const status = t.barberproSubscriptionStatus ?? 'trial';
    const trialEndsAt = t.trialEndsAt ? new Date(t.trialEndsAt) : null;
    const now = new Date();

    // Grace period: 48h de tolerância após expirar antes de bloquear
    // Evita barrar barbeiros que acordam cedo quando o trial expirou de madrugada
    const GRACE_MS = 48 * 60 * 60 * 1000;
    const trialExpiredPastGrace = trialEndsAt && (now.getTime() - trialEndsAt.getTime()) > GRACE_MS;
    const trialExpiredInGrace   = trialEndsAt && trialEndsAt < now && !trialExpiredPastGrace;

    // Bloquear apenas se expirado ou cancelado (nunca bloquear pending/overdue para não impedir pagamento)
    const isBlocked = status === 'expired' || status === 'cancelled' || (status === 'trial' && trialExpiredPastGrace);
    if (isBlocked) {
      if (req.path.startsWith('/admin/configuracoes') || req.path.startsWith('/admin/logout')) {
        (req as any).adminSession = session;
        return next();
      }
      return res.redirect("/admin/configuracoes?tab=pagamentos&expired=1");
    }
    // Durante o grace period: mostra banner de aviso sem bloquear
    if (status === 'trial' && trialExpiredInGrace && trialEndsAt) {
      const elapsed = now.getTime() - trialEndsAt.getTime();
      const hoursLeft = Math.max(0, Math.ceil((GRACE_MS - elapsed) / 3600000));
      (req as any).trialInGrace = { hoursLeft };
    }
    return next();
  } catch {
    return next(); // Em caso de erro, não bloquear
  }
}


// ── Magic Link — autenticação via email para conversão de trial ──────────────
// Token é um JWT-like simples assinado com JWT_SECRET, válido por 7 dias.
// Contém: tenantId + barberId + type = 'trial_conversion'
// NÃO concede acesso a nada além da tela de pagamento.

const MAGIC_LINK_MAX_AGE = 7 * 24 * 60 * 60; // 7 dias em segundos

async function encodeMagicToken(tenantId: number, barberId: number): Promise<string> {
  const { ENV } = await import("./_core/env");
  const payload = { tenantId, barberId, type: "trial_conversion", ts: Date.now() };
  const data = Buffer.from(JSON.stringify(payload)).toString("base64url");
  // Assinar com HMAC simples usando JWT_SECRET
  const crypto = await import("crypto");
  const sig = crypto.createHmac("sha256", ENV.cookieSecret || "barber-pro-magic")
    .update(data).digest("base64url");
  return `${data}.${sig}`;
}

async function decodeMagicToken(token: string): Promise<{ tenantId: number; barberId: number } | null> {
  try {
    const { ENV } = await import("./_core/env");
    const [data, sig] = token.split(".");
    if (!data || !sig) return null;
    const crypto = await import("crypto");
    const expected = crypto.createHmac("sha256", ENV.cookieSecret || "barber-pro-magic")
      .update(data).digest("base64url");
    if (sig !== expected) return null;
    const payload = JSON.parse(Buffer.from(data, "base64url").toString("utf-8"));
    if (payload.type !== "trial_conversion") return null;
    if (Date.now() - payload.ts > MAGIC_LINK_MAX_AGE * 1000) return null;
    return { tenantId: payload.tenantId, barberId: payload.barberId };
  } catch { return null; }
}

export async function generateMagicLink(tenantId: number, baseUrl = "https://usebarberpro.com"): Promise<{ solo: string; team: string; studio: string; base: string }> {
  const barbers = await db.getAllBarbers(tenantId) as any[];
  const admin = barbers.find((b: any) => b.role === "super_admin") ?? barbers[0];
  if (!admin) throw new Error("Nenhum barbeiro encontrado para o tenant");
  const token = await encodeMagicToken(tenantId, admin.id);
  const base = `${baseUrl}/admin/plano?token=${token}`;
  return {
    base,
    solo:   `${base}&plan=solo`,
    team:   `${base}&plan=team`,
    studio: `${base}&plan=studio`,
  };
}

