  // POST /admin-api/pix-for-appointment — Gera cobrança Pix via Asaas para pagamento presencial
  app.post("/admin-api/pix-for-appointment", requireAdminAuth, async (req: Request, res: Response) => {
    try {
      if (!asaasEnabled) { res.status(503).json({ error: "Pagamento online não configurado." }); return; }
      const session = (req as any).adminSession as { barberId: number };
      const barber = await db.getBarberById(session.barberId);
      if (!barber?.tenantId) { res.status(400).json({ error: "Tenant não encontrado." }); return; }

      const { appointmentId, clientId, clientName, clientPhone, amount, description } = req.body;
      if (!amount || parseFloat(amount) <= 0) { res.status(400).json({ error: "Valor inválido." }); return; }

      // Buscar asaasApiKey da subconta do tenant — pagamento vai direto para a barbearia
      const dbConn = await db.getDb();
      let subAccountApiKey: string | undefined;
      if (dbConn) {
        const tenantRow = await dbConn.execute(sql`SELECT "asaasApiKey" FROM tenants WHERE id = ${barber.tenantId} LIMIT 1`) as any;
        const tenantData = Array.isArray(tenantRow) ? tenantRow[0]?.[0] : tenantRow?.rows?.[0];
        subAccountApiKey = tenantData?.asaasApiKey || undefined;
      }
      if (!subAccountApiKey) { res.status(400).json({ error: "Subconta Asaas não configurada para esta barbearia. Ative os pagamentos online nas configurações." }); return; }

      // Criar ou buscar cliente no Asaas
      const asaasCustomerId = await getOrCreateAsaasCustomer({
        name: clientName || "Cliente",
        mobilePhone: clientPhone ? clientPhone.replace(/\D/g, "") : undefined,
        externalReference: clientId ? String(clientId) : undefined,
      }, subAccountApiKey);

      // Criar cobrança Pix na subconta da barbearia
      const charge = await createAsaasCharge({
        customer: asaasCustomerId,
        billingType: "PIX",
        value: parseFloat(amount),
        dueDate: asaasDefaultDueDate(),
        description: description || "Serviço — Barber Pro",
        externalReference: appointmentId ? String(appointmentId) : undefined,
      }, subAccountApiKey);

      res.json({
        ok: true,
        paymentId: charge.id,
        pixQrCode: charge.pixQrCode ?? null,
        pixCopyCola: charge.pixCopyCola ?? null,
        invoiceUrl: charge.invoiceUrl ?? null,
        value: charge.value,
        dueDate: charge.dueDate,
      });
    } catch (e: any) {
      console.error("[pix-for-appointment]", e.message);
      res.status(500).json({ error: e.message });
    }
  });

  // POST /admin-api/cancel-asaas-charge — Cancelar cobrança Asaas pendente
  app.post("/admin-api/cancel-asaas-charge", requireAdminAuth, async (req: Request, res: Response) => {
    try {
      const { asaasPaymentId } = req.body;
      if (!asaasPaymentId) { res.status(400).json({ error: "asaasPaymentId é obrigatório" }); return; }
      if (!asaasEnabled) { res.status(503).json({ error: "Asaas não configurado" }); return; }
      const ASAAS_API_KEY = process.env.ASAAS_API_KEY ?? "";
      const ASAAS_SANDBOX = process.env.ASAAS_SANDBOX === "true";
      const ASAAS_BASE_URL = ASAAS_SANDBOX ? "https://sandbox.asaas.com/api/v3" : "https://api.asaas.com/v3";
      await axios.delete(`${ASAAS_BASE_URL}/payments/${asaasPaymentId}`, {
        headers: { "access_token": ASAAS_API_KEY, "Content-Type": "application/json" },
        timeout: 15000,
      });
      const dbConn = await db.getDb();
      if (dbConn) {
        await dbConn.execute(sql`UPDATE online_payments SET status = 'cancelled', updatedAt = NOW() WHERE asaasPaymentId = ${asaasPaymentId}`);
      }
      res.json({ ok: true });
    } catch (e: any) {
      const msg = e?.response?.data?.errors?.[0]?.description || e?.response?.data?.description || e.message;
      console.error("[cancel-asaas-charge]", msg);
      res.status(500).json({ error: msg });
    }
  });
  // POST /admin-api/payment-link — Buscar ou gerar link de pagamento para reenvio por WhatsApp
  app.post("/admin-api/mark-payment-paid", requireAdminAuth, async (req: Request, res: Response) => {
    try {
      const { asaasPaymentId } = req.body;
      if (!asaasPaymentId) { res.status(400).json({ error: "asaasPaymentId é obrigatório" }); return; }
      const session = (req as any).adminSession as { barberId: number; role: string };
      const barber = await db.getBarberById(session.barberId);
      const tenantId = barber?.tenantId ?? null;
      if (!tenantId) { res.status(403).json({ error: "Sem permissão" }); return; }
      const dbConn = await db.getDb();
      if (!dbConn) { res.status(503).json({ error: "Banco indisponível" }); return; }
      // Verificar se o pagamento pertence ao tenant antes de atualizar
      const rows = await dbConn.execute(sql`SELECT id FROM online_payments WHERE "asaasPaymentId" = ${asaasPaymentId} AND "tenantId" = ${tenantId}`) as any;
      const found = Array.isArray(rows) ? rows[0]?.[0] : rows?.rows?.[0];
      if (!found) { res.status(404).json({ error: "Pagamento não encontrado" }); return; }
      await dbConn.execute(sql`UPDATE online_payments SET status = 'paid', "paidAt" = NOW() WHERE "asaasPaymentId" = ${asaasPaymentId} AND "tenantId" = ${tenantId}`);
      res.json({ ok: true });
    } catch (e: any) {
      console.error("[mark-payment-paid]", e.message);
      res.status(500).json({ error: e.message });
    }
  });

  app.post("/admin-api/payment-link", requireAdminAuth, async (req: Request, res: Response) => {
    try {
      const { appointmentId, slug } = req.body;
      if (!appointmentId || !slug) { res.status(400).json({ error: "appointmentId e slug são obrigatórios" }); return; }
      const session = (req as any).adminSession as { barberId: number; role: string };
      const barber = await db.getBarberById(session.barberId);
      const tenantId = barber?.tenantId ?? null;
      // Buscar dados do agendamento
      const appt = await db.getAppointmentById(parseInt(appointmentId));
      if (!appt) { res.status(404).json({ error: "Agendamento não encontrado" }); return; }
      // Buscar dados do cliente
      const client = appt.clientId ? await db.getClientById(appt.clientId) : null;
      // Buscar configurações da loja
      const settings = await db.getShopSettings(tenantId);
      // Verificar se já existe pagamento pendente no banco
      const dbConn = await db.getDb();
      let existingPayment: any = null;
      if (dbConn && tenantId) {
        const raw = await dbConn.execute(sql`
          SELECT invoiceUrl, asaasPaymentId FROM online_payments
          WHERE tenantId = ${tenantId} AND referenceId = ${parseInt(appointmentId)} AND status = 'pending'
          ORDER BY createdAt DESC LIMIT 1
        `) as any;
        const rows = Array.isArray(raw) ? (raw[0] as any[]) : (raw?.rows ?? []);
        if (rows.length > 0) existingPayment = rows[0];
      }
      // Montar URL de pagamento — usar invoiceUrl do Asaas se disponível, senão link da página pública
      const baseUrl = process.env.PUBLIC_URL || `https://usebarberpro.com`;
      const publicPayUrl = `${baseUrl}/pub/${slug}`;
      const paymentUrl = existingPayment?.invoiceUrl || publicPayUrl;
      res.json({
        ok: true,
        paymentUrl,
        clientName: (client as any)?.name || '',
        clientPhone: (client as any)?.phone || '',
        shopName: settings?.shopName || '',
        hasExistingCharge: !!existingPayment,
      });
    } catch (e: any) {
      console.error("[payment-link]", e.message);
      res.status(500).json({ error: e.message });
    }
  });
  // GET /admin-api/waitlist-count — Retorna contagem de lista de espera do dia
  app.get("/admin-api/waitlist-count", requireAdminAuth, async (req: Request, res: Response) => {
    try {
      const session = (req as any).adminSession as { barberId: number };
      const barber = await db.getBarberById(session.barberId);
      const tenantId = barber?.tenantId;
      if (!tenantId) { res.json({ count: 0 }); return; }
      const dbConn = await db.getDb();
      if (!dbConn) { res.json({ count: 0 }); return; }
      const today = new Date().toISOString().split('T')[0];
      const rows = await dbConn.execute(sql`SELECT COUNT(*) as cnt FROM waitlist w JOIN barbers b ON b.id = w."barberId" WHERE b."tenantId" = ${tenantId} AND w.date >= ${today} AND w.status = 'waiting'`) as any;
      const row = Array.isArray(rows) ? (rows[0] as any[])[0] : (rows?.rows ?? [])[0];
      res.json({ count: parseInt(row?.cnt ?? '0') });
    } catch(e) { res.json({ count: 0 }); }
  });

  // GET /admin-api/agenda-day — Retorna JSON com agendamentos de um dia (para navegação sem reload)
  app.get("/admin-api/agenda-day", requireAdminAuth, async (req: Request, res: Response) => {
    try {
      const session = (req as any).adminSession as { barberId: number; role: string };
      const barber = await db.getBarberById(session.barberId);
      const tenantId = barber?.tenantId ?? null;
      const dateStr = (req.query.date as string) || today();
      const filterBarberId = req.query.barberId ? parseInt(req.query.barberId as string) : null;

      const allAppointments = await db.getAllAppointmentsByDate(dateStr, tenantId);
      const filtered = filterBarberId
        ? allAppointments.filter((a: any) => a.barberId === filterBarberId)
        : allAppointments;

      // Buscar pagamentos online associados
      const dbConn = await db.getDb();
      const paidAppointmentIds = new Set<number>();
      if (dbConn && filtered.length > 0) {
        try {
          const ids = filtered.map((a: any) => a.id);
          const pmtRows = await dbConn.execute(sql`
            SELECT "referenceId" FROM online_payments
            WHERE "referenceId" IN (${sql.raw(ids.join(","))})
            AND "chargeType" = 'appointment'
            AND status IN ('received','confirmed')
          `) as any;
          const rows = Array.isArray(pmtRows) ? (pmtRows[0] as any[]) : (pmtRows?.rows ?? []);
          rows.forEach((r: any) => paidAppointmentIds.add(Number(r.referenceId)));
        } catch {}
      }

      res.json({
        ok: true,
        date: dateStr,
        appointments: filtered.map((a: any) => ({
          id: a.id,
          clientName: a.clientName ?? "",
          clientPhone: a.clientPhone ?? "",
          serviceId: a.serviceId,
          serviceName: a.serviceNames ?? a.serviceName ?? "",
          servicePrice: a.servicePrice ?? "0",
          barberId: a.barberId,
          barberName: a.barberName ?? "",
          date: a.date,
          startTime: a.startTime ?? "",
          endTime: a.endTime ?? "",
          status: a.status,
          notes: a.notes ?? "",
          onlinePaid: paidAppointmentIds.has(a.id),
        })),
      });
    } catch (e: any) {
      res.status(500).json({ ok: false, error: e.message });
    }
  });

  // GET /admin-api/next-appointment — Retorna JSON com o próximo agendamento do dia
  app.get("/admin-api/next-appointment", requireAdminAuth, async (req: Request, res: Response) => {
    try {
      const session = (req as any).adminSession as { barberId: number; role: string };
      const barber = await db.getBarberById(session.barberId);
      const tenantId = barber?.tenantId ?? null;
      const dateStr = today();
      const appointments = await db.getAllAppointmentsByDate(dateStr, tenantId);
      const barbers = await db.getAllBarbers(tenantId);
      const barberMap: Record<number, string> = Object.fromEntries(barbers.map((b) => [b.id, b.name]));
      // Calcular hora atual em BRT (UTC-3)
      const nowMinutes = (() => {
        const now = new Date();
        const brt = new Date(now.getTime() - 3 * 60 * 60 * 1000);
        return brt.getUTCHours() * 60 + brt.getUTCMinutes();
      })();
      const next = appointments
        .filter((a: any) => {
          if (!a.startTime) return false;
          const [h, m] = a.startTime.split(':').map(Number);
          return (h * 60 + m) >= nowMinutes && ['scheduled', 'confirmed'].includes(a.status);
        })
        .sort((a: any, b: any) => {
          const [ah, am] = a.startTime.split(':').map(Number);
          const [bh, bm] = b.startTime.split(':').map(Number);
          return (ah * 60 + am) - (bh * 60 + bm);
        })[0] ?? null;
      if (!next) { res.json({ clientName: null }); return; }
      res.json({
        clientName: (next as any).clientName ?? 'Cliente',
        serviceName: (next as any).serviceName ?? (next as any).serviceNames ?? '',
        barberName: barberMap[(next as any).barberId] ?? '',
        startTime: ((next as any).startTime ?? '').substring(0, 5),
        status: (next as any).status ?? 'scheduled',
      });
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

